function MusicPlayerCell:Awake()
    self._eventUpdateNewState = Events.AddListener(Constants.EventNames.PlayerCDUpdateNewState, Bind(self, self.UpdateNewImgVisible))
    SetButtonAction(self.controller.transform:Find("BtnRoot"), function()
        self.ChapterList:JumpTo(self.index - 1)
    end)
    SetButtonAction(self.BtnHeart, function()
        if self.clickCb then
            self.clickCb(self.cdId)
            self:UpdateLikeImgVisible()
        end
    end)
end

function MusicPlayerCell:Start()

end

function MusicPlayerCell:OnDestroy()
    Events.RemoveListener(Constants.EventNames.PlayerCDUpdateNewState, self._eventUpdateNewState)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

