function MusicPlayerCell:UpdateContent(data)
    self.index   = data.index
    self.cdId    = checkInt(data.id)
    self.clickCb = data.cb
    self.likeIdMap = data.idMap
    ---@type MusicPlayerVo
    self.musicVo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", self.cdId)
    if self.musicVo == nil then
        return
    end

    local isUnlock = playerDojo:CheckAlbumIsUnlocked(self.musicVo.id)
    KTool.SetActive(self.LockNode,not isUnlock)
    KTool.SetActive(self.SmallLockNode, not isUnlock)
    KTool.SetActive(self.ImgCover2, isUnlock)
    KTool.SetActive(self.BtnHeart, isUnlock)
    KTool.SetActive(self.SmallBtnHeart, isUnlock)
    KTool.SetActive(self.ImgLimited, isUnlock and checkInt(self.musicVo.tagType) > 0)
    KTool.SetActive(self.SmallImgLimited, isUnlock and checkInt(self.musicVo.tagType) > 0)

    CfUtils.FillImage(self.SmallImgCoverPhoto, self.musicVo.coverImg)
    CfUtils.FillImage(self.ImgCoverPhoto, self.musicVo.coverImg)
    CfUtils.FillImage(self.ImgCover, self.musicVo.coverImg)
    CfUtils.SetUISwitchImage(self.ImgLimited, self.musicVo.tagType)
    CfUtils.SetUISwitchImage(self.SmallImgLimited, self.musicVo.tagType)

    self:UpdateLikeImgVisible()
    self:UpdateNewImgVisible()
end

function MusicPlayerCell:UpdateSelectedNode()
    cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))
    end)
end

function MusicPlayerCell:UpdateNewImgVisible()
    local visible = PlayerInfoUtils.CheckIsCDHasNewById(self.cdId)
    KTool.SetActive(self.ImgNew, visible)
    KTool.SetActive(self.SmallImgNew, visible)
end

function MusicPlayerCell:UpdateLikeImgVisible()
    local isLike = self.likeIdMap[self.cdId] == true
    CfUtils.SetUISwitchImage(self.ImgHeart, isLike and 1 or 2)
    CfUtils.SetUISwitchImage(self.SmallImgHeart, isLike and 1 or 2)
    local animation = self.ImgHeart.transform:GetComponent(typeof(CS.UnityEngine.Animation))
    if animation then
        animation:Play(isLike and "UIMusicPlayDialogChapterListCellHeartIdle" or "UIMusicPlayDialogChapterListCellHeartLoop")
    end
end

return MusicPlayerCell